-- ============================================================
-- Migration 006 — Kategori ağacı ONARIM (UUID'den bağımsız)
-- Bozuk/yetim parent bağlarını KODA göre yeniden kurar. Mevcut UUID
-- durumu ne olursa olsun doğru 3 kademeli ağacı garanti eder. İDEMPOTENT.
-- Uygula: phpMyAdmin > SQL sekmesi > yapıştır > Çalıştır (Git).
-- SONRA: her cihazda uygulamayı sert yenile + çıkış/giriş (ya da 'Sunucudan yenile').
-- ============================================================
SET NAMES utf8mb4;
SET @tenant := (SELECT id FROM tenants ORDER BY created_at ASC LIMIT 1);
SET @now := CURRENT_TIMESTAMP(3);

DROP TEMPORARY TABLE IF EXISTS cat_seed;
CREATE TEMPORARY TABLE cat_seed (
  code VARCHAR(16) NOT NULL PRIMARY KEY,
  parent_code VARCHAR(16) NULL,
  name_tr VARCHAR(120) NOT NULL,
  name_en VARCHAR(120) NULL,
  sku_template VARCHAR(190) NULL,
  default_count_mode VARCHAR(16) NOT NULL,
  attribute_schema LONGTEXT NULL,
  sort_order INT NOT NULL
) CHARACTER SET utf8mb4;


-- 1) Mevcut tüm kategorileri soft-delete (yeni ağaçta olanlar 2. adımda dirilir)
UPDATE categories SET deleted_at=@now, updated_at=@now
 WHERE tenant_id=@tenant AND deleted_at IS NULL;

-- 2) Mevcut kodları GÜNCELLE+DİRİLT (id KORUNUR → parça bağı sağlam), yeni kodları EKLE.
--    parent_id şimdilik NULL; 3. adımda KOD ile bağlanır.
SELECT COALESCE(ex.id, UUID()), @tenant, NULL, s.code, s.name_tr, s.name_en, s.sku_template,
       s.default_count_mode, s.attribute_schema, s.sort_order, @now, NULL
  FROM cat_seed s
  LEFT JOIN categories ex ON ex.tenant_id=@tenant AND ex.code=s.code
ON DUPLICATE KEY UPDATE
  name_tr=VALUES(name_tr), name_en=VALUES(name_en), sku_template=VALUES(sku_template),
  default_count_mode=VALUES(default_count_mode), attribute_schema=VALUES(attribute_schema),
  sort_order=VALUES(sort_order), updated_at=@now, deleted_at=NULL;

-- 3) parent_id'yi KOD üzerinden bağla (ASIL ONARIM — UUID'den bağımsız).
UPDATE categories c
  JOIN cat_seed s ON s.code=c.code
  LEFT JOIN categories p ON p.tenant_id=@tenant AND p.code=s.parent_code AND p.deleted_at IS NULL
SET c.parent_id = p.id, c.updated_at=@now
 WHERE c.tenant_id=@tenant AND c.deleted_at IS NULL;

-- 4) Ağaçta artık olmayan (silik) kategoriye bağlı parçaları serbest bırak
UPDATE parts pt JOIN categories c ON c.id=pt.category_id
   SET pt.category_id=NULL, pt.updated_at=@now
 WHERE pt.tenant_id=@tenant AND c.deleted_at IS NOT NULL;

DROP TEMPORARY TABLE IF EXISTS cat_seed;

